# Part-4 lane a: AI poses + the pair seen from behind. Run: python stil/canli/prompts/make_p4_a.py
import os

HERE = os.path.dirname(os.path.abspath(__file__))
HEAD = "Use your built-in image_gen tool to generate exactly ONE image, 16:9 landscape. Do not copy or move any files and do not run shell commands; just generate it, then print DONE.\n\n"
BG = "\n\nBackground: ONE flat solid pure magenta (#FF00FF), completely uniform, no shadow, no floor line, no ground, no window, no glass, no wave, no street drawn. ABSOLUTELY NO text, letters, numbers, logos, watermarks, no other characters. Palette only navy, cream, moon yellow (+ magenta background). No 3D render look, no photorealism, no soft shading.\n"
RULES = "\n\nRules: one camera perspective for the set; the head is NOT turned more than 30 degrees relative to the torso (a turn is a whole-body turn); hands really touch and grip what they hold; exactly two arms, two legs, at most five fingers per hand, no extra, missing, doubled or stretched limbs, every joint bends the natural way; exactly one figure."
AI = HEAD + """The FIRST attached image is the APPROVED design of the AI character (silk-screen style); the SECOND is an approved pose drawing of her in this same film. Draw the SAME character, ONE single figure, centred: smooth genderless slender body, cream-white (#F3EFE4) fill with fine navy stipple speckle, a thin navy outline, bald round head, NO face at all except ONE short vertical navy cursor line on the face on the side of the head she faces (exactly like the reference). No clothes, no hair, no ears, no nose, no mouth. Same proportions as the reference (small round head, long slim body).

"""
FULL = "FULL BODY, nothing cropped, feet and hands included, fully inside the image with a margin. "
P = {}
P['p4-a-run'] = AI + FULL + "Set camera: a night street seen in a FLAT SIDE VIEW (pure profile). Pose: she RUNS in pure profile facing RIGHT (cursor line on the RIGHT side of the head): the FLIGHT phase of a sprint, BOTH FEET OFF THE GROUND, the legs scissored (front thigh raised forward with the knee bent, the rear leg stretched back with the foot kicked up behind), both arms pumping, each BENT at about 90 degrees at the elbow (near arm forward when the near leg is back, the other arm swung back), the torso leaning forward a little, the head level and facing forward." + RULES + BG
P['p4-a-swept'] = AI + FULL + "Set camera: a wide flat frame; she is drawn as a flat 2D figure. Pose: she has been LIFTED off her feet by a giant wave (do not draw the wave, the ground or anything else): her whole body is DIAGONAL in the air, tumbling BACKWARD and UP, the head toward the upper right and tilted back, the back arched slightly, both ARMS FLUNG UP and OUT to the sides and above her head with open hands, the LEGS trailing loosely below and behind her, knees softly bent, feet hanging, no foot touching anything. Natural joints, a limp weightless tumble, as if thrown upward by water. Cursor line on the side of the head that faces the upper right, drawn small and clean like the reference." + RULES.replace("one camera perspective for the set; ", "flat 2D drawing; ") + BG
P['p4-a-cross'] = AI + FULL + "Set camera: the coda, a FLAT SIDE VIEW (pure profile). The second attached image shows her facing RIGHT; in THIS drawing she must face LEFT (cursor line on the LEFT side of the head). Pose: she takes a long DECISIVE STEP FORWARD to the left: the front (left-most) foot is LANDING flat on the ground with the knee slightly bent, the back foot is behind her on its TOES with the heel lifted, the legs wide apart, the torso upright, the head LEVEL looking straight ahead. Her NEAR arm reaches forward to the left at CHEST height, the arm almost straight, with an OPEN HAND (fingers together, palm facing forward and slightly up, as if offering it); the far arm swings back behind her." + RULES + BG
P['p4-a-pair-back'] = HEAD + """The attached images: the FIRST is the canonical design of the HUMAN character (a navy silhouette with a thin cream rim light, messy short hair, yellow sticky notes pinned on his shoulders and back), the SECOND is the approved design of the AI character (cream-white body with fine navy stipple, thin navy outline, bald round head with one vertical navy cursor line as her only face feature), the THIRD is an illustration showing the pose idea only (two figures seen from behind holding hands) - take only the pose idea, not its style, scenery or colours.

Draw exactly TWO figures SEEN FROM BEHIND (back views, we see the backs of their heads and bodies), standing SIDE BY SIDE on flat ground, full body, nothing cropped, feet included, fully inside the image with a margin, centred as a pair, a small gap between the bodies at shoulder level. On the LEFT of the image: the HUMAN, a navy silhouette with a thin cream rim, his messy short hair seen from behind, the same yellow (#F0D35A) sticky-note pattern on his back and shoulders as in the first image, barefoot, standing calmly. On the RIGHT of the image: the AI, cream-white body with fine navy stipple and a thin navy outline, the BACK of her smooth round bald head (NO eye, NO cursor line, no face visible from behind), slim body, barefoot. They HOLD HANDS between them at hip height: HIS RIGHT hand (the one on the side toward her) CLASPS HER LEFT hand (the one toward him); the two hands are visibly touching, fingers interlaced, at hip height, each arm hanging naturally down toward the clasp. Both of them tilt their heads very slightly UP and FORWARD, as if looking at a moon that is NOT drawn. They are about the SAME HEIGHT (she is about as tall as he is; heads at nearly the same level). Camera: one flat eye-level view from behind, both figures on the same ground line.

Rules: exactly two figures, each with exactly two arms and two legs, at most five fingers per hand, no extra, missing, doubled or stretched limbs, the natural joint directions, no morphing between the two bodies.""" + BG.replace("no window, no glass, no wave, no street drawn", "no window, no glass, no moon, no wave, no street drawn")
for k, v in P.items():
    open(os.path.join(HERE, k + '.txt'), 'w', encoding='utf8').write(v)
print(len(P), 'prompts')
